"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[4940],{7154(e,n,t){t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>c,default:()=>h,frontMatter:()=>l,metadata:()=>i,toc:()=>u});const i=JSON.parse('{"id":"part2-backend-platform-security/tenant-iam-ad-groups","title":"Tenant Isolation, Cloud IAM, and Organization Group Gating","description":"You\u2019re dealing with three different \u201cwho are you / what can you access\u201d systems that often get mixed up:","source":"@site/docs/part2-backend-platform-security/12-tenant-iam-ad-groups.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/12-tenant-iam-ad-groups","permalink":"/tutorials/part2-backend-platform-security/12-tenant-iam-ad-groups","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":12,"frontMatter":{"title":"Tenant Isolation, Cloud IAM, and Organization Group Gating","slug":"/part2-backend-platform-security/12-tenant-iam-ad-groups","description":"You\u2019re dealing with three different \u201cwho are you / what can you access\u201d systems that often get mixed up:","sidebar_label":"13. Tenant isolation, IAM, and groups","pagination_label":"13. Tenant isolation, IAM, and groups","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"12. End-user vs workload identity","permalink":"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity"},"next":{"title":"14. GCP workload identity","permalink":"/tutorials/part2-backend-platform-security/11-gcp-workload-identity"}}');var a=t(4848),o=t(8453),s=t(8172);const r=JSON.parse('{"sourcePath":"part2-backend-platform-security/12-tenant-iam-ad-groups.html","route":"/part2-backend-platform-security/12-tenant-iam-ad-groups","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"Tenant Isolation, Cloud IAM, and Organization Group Gating","title":"Tenant Isolation, Cloud IAM, and Organization Group Gating","description":"You\u2019re dealing with three different \u201cwho are you / what can you access\u201d systems that often get mixed up:","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"the-one-sentence-mental-model","label":"The one-sentence mental model"},{"id":"scenario-1-normal-end-user-uses-your-app-tenant-isolation","label":"Scenario 1 \u2014 Normal end user uses your app (tenant isolation)"},{"id":"scenario-2-internal-employee-sees-buckets-in-gcp-console-iam","label":"Scenario 2 \u2014 Internal employee sees buckets in GCP Console (IAM)"},{"id":"scenario-3-app-is-accessible-only-to-an-ad-group-org-allowlist-gate","label":"Scenario 3 \u2014 App is accessible only to an AD group (org allowlist gate)"},{"id":"scenario-3-has-two-enforcement-methods","label":"Scenario 3 has two enforcement methods"},{"id":"how-all-three-fit-together-the-3-lane-model","label":"How all three fit together (the \u201c3-lane model\u201d)"},{"id":"common-mistakes-and-fixes","label":"Common mistakes (and fixes)"},{"id":"bootstrap-decision-tree-the-exact-order","label":"Bootstrap decision tree (the exact order)"}],"html":"<div class=\\"container\\">\\n\\n    \\n\\n    <p>You\u2019re dealing with three different \u201cwho are you / what can you access\u201d systems that often get mixed up:</p>\\n    <ol>\\n        <li><strong>Application tenancy</strong> (<code>tenant_id</code>, <code>user_id</code>) \u2192 your SaaS data isolation</li>\\n        <li><strong>Cloud IAM</strong> \u2192 who can see/use GCP resources (Console, buckets, secrets)</li>\\n        <li><strong>Org group gating</strong> (AD/Workspace groups) \u2192 who is allowed to use your app at all</li>\\n    </ol>\\n\\n    <p>They can interact, but they\u2019re not the same thing.</p>\\n\\n    <div class=\\"tr-note\\">\\n        <strong>How this chapter relates to Chapter 10</strong>\\n        <a href=\\"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity\\">Chapter 10</a> owns the\\n        core three-lane model: end-user identity, application authorization,\\n        and workload identity/IAM. This chapter keeps the same concepts but\\n        rearranges them around the enterprise policy question: tenant\\n        bootstrap, AD/Workspace group gating, and common operational mistakes.\\n    </div>\\n\\n    <hr>\\n\\n    <div class=\\"mental-model\\">\\n        <h2 id=\\"the-one-sentence-mental-model\\">The one-sentence mental model</h2>\\n        <ul>\\n            <li><strong>IAM</strong> controls access to GCP resources (projects, buckets, secrets).</li>\\n            <li><strong>Tenancy</strong> controls access to your app\u2019s data (documents, rows, search results).</li>\\n            <li><strong>AD/Group gating</strong> controls who can even use the app (coarse allowlist), before tenancy even matters.</li>\\n        </ul>\\n    </div>\\n\\n    <figure class=\\"figure-card\\">\\n      <svg viewBox=\\"0 0 1040 420\\" role=\\"img\\" aria-labelledby=\\"identity-lanes-title identity-lanes-desc\\">\\n        <title id=\\"identity-lanes-title\\">Three distinct identity and authorization lanes</title>\\n        <desc id=\\"identity-lanes-desc\\">User authentication enters an application gate, tenant authorization scopes data, and workload identity accesses cloud services.</desc>\\n        <defs>\\n          <marker id=\\"lane-arrow-blue\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#1769e0\\"></path>\\n          </marker>\\n          <marker id=\\"lane-arrow-purple\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#7548d8\\"></path>\\n          </marker>\\n          <marker id=\\"lane-arrow-green\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#14875a\\"></path>\\n          </marker>\\n        </defs>\\n\\n        <rect x=\\"30\\" y=\\"45\\" width=\\"980\\" height=\\"90\\" rx=\\"14\\" fill=\\"#e8f2ff\\" stroke=\\"#1769e0\\" stroke-width=\\"2\\"></rect>\\n        <text x=\\"65\\" y=\\"80\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Lane A: end-user identity</text>\\n        <text x=\\"65\\" y=\\"109\\" font-size=\\"15\\" fill=\\"#4f6078\\">OIDC login -&gt; access token -&gt; verified (issuer, subject)</text>\\n        <line x1=\\"420\\" y1=\\"92\\" x2=\\"930\\" y2=\\"92\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#lane-arrow-blue)\\"></line>\\n        <text x=\\"690\\" y=\\"78\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#1769e0\\">Who initiated this request?</text>\\n\\n        <rect x=\\"30\\" y=\\"165\\" width=\\"980\\" height=\\"90\\" rx=\\"14\\" fill=\\"#f1ecff\\" stroke=\\"#7548d8\\" stroke-width=\\"2\\"></rect>\\n        <text x=\\"65\\" y=\\"200\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Lane B: application authorization</text>\\n        <text x=\\"65\\" y=\\"229\\" font-size=\\"15\\" fill=\\"#4f6078\\">group gate -&gt; tenant membership -&gt; role -&gt; row/search/object filter</text>\\n        <line x1=\\"500\\" y1=\\"212\\" x2=\\"930\\" y2=\\"212\\" stroke=\\"#7548d8\\" stroke-width=\\"3\\" marker-end=\\"url(#lane-arrow-purple)\\"></line>\\n        <text x=\\"720\\" y=\\"198\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#7548d8\\">Which application data is allowed?</text>\\n\\n        <rect x=\\"30\\" y=\\"285\\" width=\\"980\\" height=\\"90\\" rx=\\"14\\" fill=\\"#e9fbf2\\" stroke=\\"#14875a\\" stroke-width=\\"2\\"></rect>\\n        <text x=\\"65\\" y=\\"320\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Lane C: workload identity</text>\\n        <text x=\\"65\\" y=\\"349\\" font-size=\\"15\\" fill=\\"#4f6078\\">service account -&gt; IAM role -&gt; Cloud SQL, Storage, Secret Manager, queues</text>\\n        <line x1=\\"555\\" y1=\\"332\\" x2=\\"930\\" y2=\\"332\\" stroke=\\"#14875a\\" stroke-width=\\"3\\" marker-end=\\"url(#lane-arrow-green)\\"></line>\\n        <text x=\\"750\\" y=\\"318\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#14875a\\">Which infrastructure calls may execute?</text>\\n      </svg>\\n      <figcaption>\\n        A request may involve all three lanes, but no lane substitutes for\\n        another. Preserve both the requesting user and executing workload in\\n        the audit record.\\n      </figcaption>\\n    </figure>\\n\\n    <hr>\\n\\n    <h2 id=\\"scenario-1-normal-end-user-uses-your-app-tenant-isolation\\">Scenario 1 \u2014 Normal end user uses your app (tenant isolation)</h2>\\n\\n    <h3 id=\\"goal\\">Goal</h3>\\n    <p>User can only access their tenant\u2019s documents, even though all tenants share the same backend + databases.</p>\\n\\n    <h3 id=\\"step-by-step\\">Step-by-step</h3>\\n    <ol>\\n        <li>\\n            <strong>User signs in with Google Workspace</strong>\\n            <ul><li>React uses OIDC (Auth Code + PKCE).</li></ul>\\n        </li>\\n        <li>\\n            <strong>React receives an access token</strong>\\n            <ul><li>This is the user\u2019s \u201cproof\u201d for your API.</li></ul>\\n        </li>\\n        <li>\\n            <strong>React calls your backend</strong>\\n            <ul><li>Every call includes:</li></ul>\\n            <pre><code class=\\"language-http\\">Authorization: Bearer &lt;access_token&gt;</code></pre>\\n        </li>\\n        <li>\\n            <strong>Backend validates token</strong>\\n            <ul><li>signature + issuer + audience + expiry.</li></ul>\\n        </li>\\n        <li>\\n            <strong>Backend maps token \u2192 identity</strong>\\n            <ul>\\n                <li><code>user_id = claims[\\"sub\\"]</code></li>\\n                <li><code>tenant_id = mapping(...)</code> (domain mapping or DB lookup)</li>\\n            </ul>\\n        </li>\\n        <li>\\n            <strong>Backend scopes all data access by tenant</strong>\\n            <ul>\\n                <li>DB queries: <code>WHERE tenant_id = ...</code></li>\\n                <li>Search queries: tenant filter</li>\\n                <li>Jobs: store <code>tenant_id</code> and enforce later</li>\\n            </ul>\\n        </li>\\n    </ol>\\n\\n    <h3 id=\\"what-this-means\\">What this means</h3>\\n    <ul class=\\"status-check\\">\\n        <li>Tenant isolation is enforced inside your app + DB/search rules.</li>\\n        <li><span class=\\"error\\">\ud83d\udeab</span> End users do not need GCP Console access or IAM permissions.</li>\\n    </ul>\\n\\n    <hr>\\n\\n    <h2 id=\\"scenario-2-internal-employee-sees-buckets-in-gcp-console-iam\\">Scenario 2 \u2014 Internal employee sees buckets in GCP Console (IAM)</h2>\\n\\n    <h3 id=\\"goal-2\\">Goal</h3>\\n    <p>Some employees can see/modify certain buckets/projects, others cannot.</p>\\n\\n    <h3 id=\\"step-by-step-2\\">Step-by-step</h3>\\n    <ol>\\n        <li>\\n            <strong>Employee logs into GCP Console</strong>\\n            <ul><li>They are a human principal.</li></ul>\\n        </li>\\n        <li>\\n            <strong>GCP checks IAM bindings</strong>\\n            <ul><li>Example: <code>group:platform-admins@company.com</code> has <code>roles/storage.admin</code> on a project.</li></ul>\\n        </li>\\n        <li>\\n            <strong>Console shows only permitted resources</strong>\\n            <ul><li>If they lack <code>storage.buckets.list</code> or equivalent permissions, the bucket won\u2019t show / access denied.</li></ul>\\n        </li>\\n    </ol>\\n\\n    <h3 id=\\"what-this-means-2\\">What this means</h3>\\n    <ul class=\\"status-check\\">\\n        <li>Console visibility = Cloud IAM (users/groups/roles on org/folder/project/bucket).</li>\\n        <li><span class=\\"error\\">\ud83d\udeab</span> This is unrelated to your app\u2019s <code>tenant_id</code>.</li>\\n    </ul>\\n    <p>The GCP Console is the cloud control plane, not your SaaS tenancy system.</p>\\n\\n    <hr>\\n\\n    <h2 id=\\"scenario-3-app-is-accessible-only-to-an-ad-group-org-allowlist-gate\\">Scenario 3 \u2014 App is accessible only to an AD group (org allowlist gate)</h2>\\n\\n    <h3 id=\\"goal-3\\">Goal</h3>\\n    <p>Only users in an org group (from Active Directory) can use the app at all.</p>\\n\\n    <h3 id=\\"step-by-step-3\\">Step-by-step</h3>\\n    <ol>\\n        <li>\\n            <strong>AD group exists</strong>\\n            <ul><li>e.g. <code>DocQA-Users</code></li></ul>\\n        </li>\\n        <li>\\n            <strong>Group is synced/federated into Google Workspace</strong>\\n            <ul><li>e.g. Google Group: <code>docqa-users@company.com</code></li></ul>\\n        </li>\\n        <li>\\n            <strong>User signs in with Google (OIDC)</strong>\\n        </li>\\n        <li>\\n            <strong>React calls <code>/auth/bootstrap</code> (or <code>/me</code>) with:</strong>\\n            <pre><code class=\\"language-http\\">Authorization: Bearer &lt;access_token&gt;</code></pre>\\n        </li>\\n        <li>\\n            <strong>Backend checks two things:</strong>\\n            <ul>\\n                <li>token is valid</li>\\n                <li>user is in <code>docqa-users@company.com</code></li>\\n            </ul>\\n        </li>\\n        <li>\\n            <strong>If allowed: backend does tenant mapping + provisioning</strong>\\n            <ul>\\n                <li>determine <code>tenant_id</code></li>\\n                <li>create user row if missing</li>\\n                <li>return identity</li>\\n            </ul>\\n        </li>\\n    </ol>\\n\\n    <h3 id=\\"what-this-means-3\\">What this means</h3>\\n    <ul class=\\"status-check\\">\\n        <li>Group gating answers: \u201cCan you use the app at all?\u201d</li>\\n        <li>Tenancy answers: \u201cWhich tenant\u2019s data can you access?\u201d</li>\\n        <li><span class=\\"error\\">\ud83d\udeab</span> Group gating is not tenancy.</li>\\n        <li><span class=\\"error\\">\ud83d\udeab</span> Group gating is not IAM.</li>\\n    </ul>\\n\\n    <hr>\\n\\n    <h2 id=\\"scenario-3-has-two-enforcement-methods\\">Scenario 3 has two enforcement methods</h2>\\n\\n    <h3 id=\\"method-a-backend-enforces-group-membership-app-level-gate\\">Method A \u2014 Backend enforces group membership (app-level gate)</h3>\\n    <h4>How it works</h4>\\n    <ul>\\n        <li>The backend validates the token and calls an org directory/groups API (or uses cached membership) to answer:</li>\\n        <li>\u201cIs <code>alice@company.com</code> in <code>docqa-users@company.com</code>?\u201d</li>\\n        <li>Not a member \u2192 403</li>\\n        <li>Member \u2192 proceed to tenant mapping + provisioning</li>\\n    </ul>\\n    <h4>Why you\u2019d choose it</h4>\\n    <ul>\\n        <li>Your backend remains the \u201csource of truth\u201d for access.</li>\\n        <li>You can combine it naturally with onboarding/provisioning logic.</li>\\n        <li>Works even if you change gateways or hosting.</li>\\n    </ul>\\n    <h4>Trade-offs</h4>\\n    <ul>\\n        <li>Backend needs permission to check group membership.</li>\\n        <li>You usually cache membership in DB to avoid checking on every request.</li>\\n    </ul>\\n\\n    <h3 id=\\"method-b-edge-gateway-enforces-group-membership-apigee-iap-style\\">Method B \u2014 Edge/gateway enforces group membership (Apigee/IAP-style)</h3>\\n    <h4>How it works</h4>\\n    <ul>\\n        <li>An edge layer sits in front of your backend.</li>\\n        <li>It verifies the caller identity and enforces a policy: \u201cmust be in allowed group\u201d</li>\\n        <li>If user is not allowed, the request never reaches FastAPI.</li>\\n    </ul>\\n    <h4>Why you\u2019d choose it</h4>\\n    <ul>\\n        <li>Strong perimeter: reduces backend exposure.</li>\\n        <li>Central policy for multiple services: auth, rate limits, quotas, logging.</li>\\n    </ul>\\n    <h4>Trade-offs</h4>\\n    <ul>\\n        <li>More moving parts.</li>\\n        <li>You still typically keep backend checks as a backstop (especially for provisioning + tenant mapping).</li>\\n    </ul>\\n\\n    <h3 id=\\"best-practice-combo\\">Best-practice combo</h3>\\n    <ul>\\n        <li>Edge gate = front door protection</li>\\n        <li>Backend gate = final authority + tenant mapping + provisioning</li>\\n        <li>(Defense in depth)</li>\\n    </ul>\\n\\n    <hr>\\n\\n    <h2 id=\\"how-all-three-fit-together-the-3-lane-model\\">How all three fit together (the \u201c3-lane model\u201d)</h2>\\n\\n    <h3 id=\\"lane-a-end-user-identity-oidc-token\\">Lane A \u2014 End-user identity (OIDC token)</h3>\\n    <ul>\\n        <li>Comes from Google login</li>\\n        <li>Arrives as <code>Authorization: Bearer ...</code></li>\\n        <li>Used to derive <code>user_id</code>/<code>tenant_id</code></li>\\n    </ul>\\n\\n    <h3 id=\\"lane-b-application-authorization-tenant-isolation\\">Lane B \u2014 Application authorization (tenant isolation)</h3>\\n    <ul>\\n        <li>DB/search filtering rules using <code>tenant_id</code></li>\\n        <li>RLS is a backstop, not the primary identity mechanism</li>\\n    </ul>\\n\\n    <h3 id=\\"lane-c-workload-identity-service-account-iam\\">Lane C \u2014 Workload identity (service account IAM)</h3>\\n    <ul>\\n        <li>Backend runs as a service account</li>\\n        <li>IAM grants that service account access to infra:</li>\\n        <li>Cloud SQL, Cloud Storage, Secret Manager, logging, queues</li>\\n        <li>Not tied to the human user</li>\\n    </ul>\\n\\n    <hr>\\n\\n    <h2 id=\\"common-mistakes-and-fixes\\">Common mistakes (and fixes)</h2>\\n\\n    <h3 id=\\"mistake-1-tenant-iam\\">Mistake 1: \u201cTenant = IAM\u201d</h3>\\n    <p>No. Tenant is inside your app; IAM is for GCP resources.<br>\\n    <strong>Fix:</strong> keep end users out of IAM; enforce tenancy in app/DB/search.</p>\\n\\n    <h3 id=\\"mistake-2-if-user-is-in-ad-group-they-re-tenant-x\\">Mistake 2: \u201cIf user is in AD group, they\u2019re tenant X\u201d</h3>\\n    <p>Not necessarily. Group is a coarse gate; tenant mapping is separate.<br>\\n    <strong>Fix:</strong> group check first, tenant mapping second.</p>\\n\\n    <h3 id=\\"mistake-3-users-should-access-buckets-directly-via-iam\\">Mistake 3: \u201cUsers should access buckets directly via IAM\u201d</h3>\\n    <p>Usually no for SaaS customers.<br>\\n    <strong>Fix:</strong> users access files via your API (or signed URLs); backend uses service account to talk to storage.</p>\\n\\n    <hr>\\n\\n    <h2 id=\\"bootstrap-decision-tree-the-exact-order\\">Bootstrap decision tree (the exact order)</h2>\\n    <p><code>/auth/bootstrap</code> (or <code>/me</code>):</p>\\n    <ol>\\n        <li>Verify token (signature, iss, aud, exp)</li>\\n        <li>Check org allowlist (AD/Workspace group) \u2192 if fail: 403</li>\\n        <li>Map to <code>tenant_id</code> (domain mapping or DB lookup) \u2192 if fail: 403</li>\\n        <li>Provision user if missing (issuer+sub key, store <code>tenant_id</code>)</li>\\n        <li>Return <code>{user_id, tenant_id, is_new_user}</code></li>\\n    </ol>\\n\\n    <h3 id=\\"typed-fastapi-bootstrap-boundary\\">Typed FastAPI bootstrap boundary</h3>\\n    <p>\\n      Keep verification, group lookup, tenant mapping, and persistence behind\\n      separate interfaces. This makes each policy independently testable and\\n      prevents the route from trusting unverified claims.\\n    </p>\\n\\n    <pre><code class=\\"language-python\\">from typing import Annotated\\n\\nfrom fastapi import Depends, FastAPI, Header, HTTPException, status\\nfrom pydantic import BaseModel\\n\\napp = FastAPI()\\n\\n\\nclass VerifiedIdentity(BaseModel):\\n    issuer: str\\n    subject: str\\n    email: str\\n    email_verified: bool\\n\\n\\nclass BootstrapResponse(BaseModel):\\n    user_id: str\\n    tenant_id: str\\n    is_new_user: bool\\n\\n\\nasync def require_identity(\\n    authorization: Annotated[str | None, Header()] = None,\\n) -&gt; VerifiedIdentity:\\n    token = extract_bearer_token(authorization)\\n    claims = await token_verifier.verify(\\n        token,\\n        expected_issuer=settings.issuer,\\n        expected_audience=settings.api_audience,\\n    )\\n    return VerifiedIdentity(\\n        issuer=claims[\\"iss\\"],\\n        subject=claims[\\"sub\\"],\\n        email=claims[\\"email\\"],\\n        email_verified=claims.get(\\"email_verified\\", False),\\n    )\\n\\n\\n@app.post(\\"/auth/bootstrap\\", response_model=BootstrapResponse)\\nasync def bootstrap(\\n    identity: Annotated[VerifiedIdentity, Depends(require_identity)],\\n) -&gt; BootstrapResponse:\\n    if not identity.email_verified:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\"A verified organization email is required\\",\\n        )\\n\\n    allowed = await directory.is_group_member(\\n        email=identity.email,\\n        group=\\"docqa-users@company.com\\",\\n    )\\n    if not allowed:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\"User is not in the application access group\\",\\n        )\\n\\n    tenant_id = await tenant_directory.resolve_membership(\\n        issuer=identity.issuer,\\n        subject=identity.subject,\\n        email=identity.email,\\n    )\\n    if tenant_id is None:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\"No active tenant membership\\",\\n        )\\n\\n    user, created = await users.upsert_external_identity(\\n        issuer=identity.issuer,\\n        subject=identity.subject,\\n        verified_email=identity.email,\\n        tenant_id=tenant_id,\\n    )\\n    return BootstrapResponse(\\n        user_id=user.id,\\n        tenant_id=tenant_id,\\n        is_new_user=created,\\n    )</code></pre>\\n\\n    <div class=\\"tr-warn\\">\\n      <strong>Concurrency requirement</strong>\\n      Enforce a database uniqueness constraint on\\n      <code>(issuer, subject)</code> and perform the lookup/upsert in one\\n      transaction. Two first requests can arrive concurrently; an in-process\\n      \u201ccheck then insert\u201d is not sufficient across workers or replicas.\\n    </div>\\n\\n</div>"}'),l={title:"Tenant Isolation, Cloud IAM, and Organization Group Gating",slug:"/part2-backend-platform-security/12-tenant-iam-ad-groups",description:"You\u2019re dealing with three different \u201cwho are you / what can you access\u201d systems that often get mixed up:",sidebar_label:"13. Tenant isolation, IAM, and groups",pagination_label:"13. Tenant isolation, IAM, and groups",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},u=[];function p(e){return(0,a.jsx)(s.A,{content:r})}function h(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(p,{...e})}):p()}}}]);